/**
 * Generate `src/generated/tokens.css` from the TypeScript theme definitions.
 * The TypeScript tokens are the single source of truth.
 */
import { mkdir } from 'node:fs/promises'
import { dark, light, themeToCss } from '../src'

const root = new URL('../', import.meta.url)
const outDir = new URL('src/generated/', root)

const css = [
  '/* Generated by scripts/gen.ts. Do not edit. */',
  '@layer dou.tokens {',
  indent(themeToCss(light, ':root,\n[data-dou-theme="light"]')),
  // `:root` too: the default theme is light, and bundlers that lower
  // `light-dark()` for older browsers (Vite does by default) only toggle it
  // where `color-scheme` is declared. Inside the layer, a page's own
  // `color-scheme` still wins.
  indent(':root,\n[data-dou-theme="light"] {\n  color-scheme: light;\n}\n'),
  indent(themeToCss(dark, '[data-dou-theme="dark"]')),
  indent('[data-dou-theme="dark"] {\n  color-scheme: dark;\n}\n'),
  '}',
  '',
].join('\n')

await mkdir(outDir, { recursive: true })
await Bun.write(new URL('tokens.css', outDir), css)

function indent(block: string): string {
  return block
    .trimEnd()
    .split('\n')
    .map((line) => `  ${line}`)
    .join('\n')
}
